.categories-subtitle {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Lobby Category Filter Tabs */
.lobby-category-filter-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.btn-lobby-tab {
  background: #ffffff;
  color: #475569;
  border: 1px solid #cbd5e1;
  border-radius: 18px;
  padding: 5px 14px;
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.btn-lobby-tab:hover {
  background: #f8fafc;
  color: #0f172a;
  border-color: #94a3b8;
}

.btn-lobby-tab.active {
  background: #ea580c;
  color: #ffffff;
  border-color: #ea580c;
  box-shadow: 0 2px 6px rgba(234, 88, 12, 0.25);
}

/* Region Filter Chips Row */
.lobby-region-chips-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding: 2px 0 4px;
}

.region-pill-btn {
  background: #ffffff;
  color: #64748b;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 4px 12px;
  font-size: 0.74rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.region-pill-btn:hover {
  border-color: #cbd5e1;
  color: #334155;
  background: #f8fafc;
}

.region-pill-btn.active {
  background: #ffedd5;
  color: #c2410c;
  border-color: #fdba74;
  font-weight: 700;
}

.cat-tag-pill.preset-tag {
  background: #ffedd5;
  color: #c2410c;
  border-color: #fdba74;
}

